50		mats := materialsMap(view)
51		if len(mats) != 2 {
52			t.Fatalf("第一次调整的结果只应有 M1、M2 两种物料，得到 %d 项: %+v", len(mats), view.Materials)
53		}
54		checkRequirement(t, mats, "M1", "1", "0", "-1") // 0.125 × 8
55		checkRequirement(t, mats, "M2", "4", "0", "-4") // 0.5 × 8
56		if _, leftover := mats["M4"]; leftover {
57			t.Fatalf("第一次调整的结果不应包含后来版本的物料 M4: %+v", mats["M4"])
58		}
59	}
60	
61	// 草稿先成功调整为 R1/v1、8 份，随后又经另一次合法调整改用 R1/v2、3 份。
62	// 用第一次的请求编号与相同内容重新提交，必须返回第一次成功的完整结果
63	// （批次编号、配方编号、版本、名称、计划份数、草稿状态与当时的数量核对），
64	// 而不是最后一次调整后的数据；当前草稿仍保留后一次调整的计划。
65	func TestUpdateDraftReplayReturnsFirstSuccessResult(t *testing.T) {
66		s := openTestStore(t)
67		registerReplayRecipes(t, s)
68		if _, err := s.CreateBatch("b1", "B1", "R1", "v2", 5); err != nil {
69			t.Fatalf("创建批次失败: %v", err)
70		}
71	
72		first, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
73		if err != nil {
74			t.Fatalf("第一次调整应成功: %v", err)
75		}
76		checkFirstAdjustView(t, first)
77	
78		// 另一次合法调整：不同版本、不同份数。
79		second, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3)
80		if err != nil {
81			t.Fatalf("第二次调整应成功: %v", err)
82		}
83		if second.RecipeVersion != "v2" || second.PlannedPortions != 3 {
84			t.Fatalf("第二次调整结果不正确: %+v", second)
85		}
86	
87		// 重新提交第一次成功的请求：返回当时的完整结果，不受后来调整影响。
88		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
89		if err != nil {
90			t.Fatalf("重复提交第一次成功的请求应成功: %v", err)
91		}
92		checkFirstAdjustView(t, replay)
93	
94		// 再次重复提交，结果仍稳定。
95		replay2, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
96		if err != nil {
97			t.Fatalf("再次重复提交应成功: %v", err)
98		}
99		checkFirstAdjustView(t, replay2)
100	
101		// 当前草稿仍保留后一次调整的计划：R1/v2、3 份。
102		got, err := s.GetBatch("B1")
103		if err != nil {
104			t.Fatalf("查询批次失败: %v", err)
105		}
106		if got.RecipeNo != "R1" || got.RecipeVersion != "v2" || got.RecipeName != "配方改版" ||
107			got.PlannedPortions != 3 || got.Status != StatusDraft {
108			t.Fatalf("当前草稿应保留后一次调整的计划（R1/v2、3 份、草稿），得到 %+v", got)
109		}
110		mats := materialsMap(got)
111		if len(mats) != 2 {
112			t.Fatalf("当前草稿只应有 M1、M4 两种物料，得到 %d 项", len(mats))
113		}
114		checkRequirement(t, mats, "M1", "750", "0", "-750") // 250 × 3
115		checkRequirement(t, mats, "M4", "6", "0", "-6")     // 2 × 3
116	}
117	
118	// 调整参数沿用原值的成功请求，重复提交时也必须返回第一次成功时已确定的
119	// 完整结果，不能按批次后来采用的配方或份数重新套用：
120	//   - 配方编号与版本同时留空 = 保留当时的配方；
121	//   - 份数传 0 = 保留当时的份数。
122	func TestUpdateDraftReplayKeepsInheritedParameters(t *testing.T) {
123		s := openTestStore(t)
124		registerReplayRecipes(t, s)
125		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
126			t.Fatalf("创建批次失败: %v", err)
127		}
128	
129		// 配方留空：保留当时的 R1/v1，只把份数改为 8。
130		keepRecipe, err := s.UpdateDraftBatch("u-keep-recipe", "B1", "", "", 8)
131		if err != nil {
132			t.Fatalf("保留配方的调整应成功: %v", err)
133		}
134		checkFirstAdjustView(t, keepRecipe)
135	
136		// 份数传 0：保留当时的 8 份，只把配方改为 R1/v2。
137		keepPortions, err := s.UpdateDraftBatch("u-keep-portions", "B1", "R1", "v2", 0)
138		if err != nil {
139			t.Fatalf("保留份数的调整应成功: %v", err)
140		}
141		if keepPortions.RecipeVersion != "v2" || keepPortions.PlannedPortions != 8 {
142			t.Fatalf("保留份数的调整结果不正确: %+v", keepPortions)
143		}
144		kpMats := materialsMap(keepPortions)
145		checkRequirement(t, kpMats, "M1", "2000", "0", "-2000") // 250 × 8
146		checkRequirement(t, kpMats, "M4", "16", "0", "-16")      // 2 × 8
147	
148		// 批次后来再改为 4 份（配方不动）。
149		if _, err := s.UpdateDraftBatch("u-later", "B1", "", "", 4); err != nil {
150			t.Fatalf("后续调整应成功: %v", err)
151		}
152	
153		// 重放“保留配方”的请求：结果必须是当时确定的 R1/v1、8 份，
154		// 不能按当前批次的 R1/v2 重新套用留空参数。
155		replayRecipe, err := s.UpdateDraftBatch("u-keep-recipe", "B1", "", "", 8)
156		if err != nil {
157			t.Fatalf("重放保留配方的请求应成功: %v", err)
158		}
159		checkFirstAdjustView(t, replayRecipe)
160	
161		// 重放“保留份数”的请求：结果必须是当时确定的 8 份，
162		// 不能按当前批次的 4 份重新套用。
163		replayPortions, err := s.UpdateDraftBatch("u-keep-portions", "B1", "R1", "v2", 0)
164		if err != nil {
165			t.Fatalf("重放保留份数的请求应成功: %v", err)
166		}
167		if replayPortions.RecipeNo != "R1" || replayPortions.RecipeVersion != "v2" ||
168			replayPortions.PlannedPortions != 8 || replayPortions.Status != StatusDraft {
169			t.Fatalf("重放结果应是第一次成功时的 R1/v2、8 份，得到 %+v", replayPortions)
170		}
171		rpMats := materialsMap(replayPortions)
172		checkRequirement(t, rpMats, "M1", "2000", "0", "-2000")
173		checkRequirement(t, rpMats, "M4", "16", "0", "-16")
174	
175		// 当前批次仍是后来确定的 R1/v2、4 份。
176		got, err := s.GetBatch("B1")
177		if err != nil {
178			t.Fatalf("查询批次失败: %v", err)
179		}
180		if got.RecipeVersion != "v2" || got.PlannedPortions != 4 || got.Status != StatusDraft {
181			t.Fatalf("当前批次应保留后来的计划（R1/v2、4 份），得到 %+v", got)
182		}
183		gotMats := materialsMap(got)
184		checkRequirement(t, gotMats, "M1", "1000", "0", "-1000") // 250 × 4
185		checkRequirement(t, gotMats, "M4", "8", "0", "-8")       // 2 × 4
186	}
187	
188	// 批次按后来的计划开始执行、登记投料并关闭后，重复提交同一成功调整
189	// 仍应成功返回原来的草稿结果；随后 GetBatch 看到的应是已关闭的实际批次，
190	// 保留后来确定的配方、份数、投料顺序及逐物料数量核对，
191	// 不因返回历史结果而回退状态或改写投料。重新打开台账后重放依然成立。
192	func TestUpdateDraftReplayAfterBatchClosed(t *testing.T) {
193		dir := t.TempDir()
194		s, err := Open(dir)
195		if err != nil {
196			t.Fatalf("Open 失败: %v", err)
197		}
198		registerReplayRecipes(t, s)
199		if _, err := s.CreateBatch("b1", "B1", "R1", "v2", 5); err != nil {
200			t.Fatalf("创建批次失败: %v", err)
201		}
202		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8); err != nil {
203			t.Fatalf("第一次调整应成功: %v", err)
204		}
205		if _, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3); err != nil {
206			t.Fatalf("第二次调整应成功: %v", err)
207		}
208	
209		// 按后来的计划（R1/v2、3 份）执行、投料并关闭。
210		if _, err := s.StartBatch("s1", "B1"); err != nil {
211			t.Fatalf("开始执行失败: %v", err)
212		}
213		feedTime := time.Date(2026, 10, 1, 9, 30, 0, 0, time.UTC)
214		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", feedTime, "张三"); err != nil {
215			t.Fatalf("投料 f1 失败: %v", err)
216		}
217		if _, err := s.AddFeeding("f2", "B1", "M4", "2", feedTime.Add(time.Hour), "李四"); err != nil {
218			t.Fatalf("投料 f2 失败: %v", err)
219		}
220		if _, err := s.AddFeeding("f3", "B1", "M1", "50", feedTime.Add(2*time.Hour), "张三"); err != nil {
221			t.Fatalf("投料 f3 失败: %v", err)
222		}
223		if _, err := s.CloseBatch("c1", "B1"); err != nil {
224			t.Fatalf("关闭批次失败: %v", err)
225		}
226	
227		// 关闭后重复提交第一次成功的调整：仍成功返回当时的草稿结果。
228		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
229		if err != nil {
230			t.Fatalf("批次关闭后重放第一次成功的调整仍应成功: %v", err)
231		}
232		checkFirstAdjustView(t, replay)
233	
234		// 实际批次不被历史结果回退：已关闭，保留后来的配方、份数、
235		// 投料顺序与逐物料数量核对。
236		checkClosedBatch := func(got *BatchView) {
237			t.Helper()
238			if got.BatchNo != "B1" || got.RecipeNo != "R1" || got.RecipeVersion != "v2" ||
239				got.RecipeName != "配方改版" || got.PlannedPortions != 3 || got.Status != StatusClosed {
240				t.Fatalf("实际批次应为已关闭的 R1/v2、3 份，得到 %+v", got)
241			}
242			if len(got.Feedings) != 3 {
243				t.Fatalf("应保留 3 条投料，得到 %d 条", len(got.Feedings))
244			}
245			wantFeedings := []FeedingView{
246				{Seq: 1, MaterialNo: "M1", Grams: "100.5", Time: feedTime, Registrar: "张三"},
247				{Seq: 2, MaterialNo: "M4", Grams: "2", Time: feedTime.Add(time.Hour), Registrar: "李四"},
248				{Seq: 3, MaterialNo: "M1", Grams: "50", Time: feedTime.Add(2 * time.Hour), Registrar: "张三"},
249			}
250			for i, want := range wantFeedings {
251				f := got.Feedings[i]
252				if f.Seq != want.Seq || f.MaterialNo != want.MaterialNo || f.Grams != want.Grams ||
253					!f.Time.Equal(want.Time) || f.Registrar != want.Registrar {
254					t.Fatalf("第 %d 条投料应为 %+v，得到 %+v", i+1, want, f)
255				}
256			}
257			mats := materialsMap(got)
258			if len(mats) != 2 {
259				t.Fatalf("已关闭批次只应有 M1、M4 两种物料，得到 %d 项", len(mats))
260			}
261			checkRequirement(t, mats, "M1", "750", "150.5", "-599.5") // 250×3，实投 100.5+50
262			checkRequirement(t, mats, "M4", "6", "2", "-4")           // 2×3
263		}
264		got, err := s.GetBatch("B1")
265		if err != nil {
266			t.Fatalf("查询已关闭批次失败: %v", err)
267		}
268		checkClosedBatch(got)
269	
270		// 重新打开台账后：重放仍返回第一次成功的草稿结果，实际批次仍是已关闭状态。
271		if err := s.Close(); err != nil {
272			t.Fatalf("关闭台账失败: %v", err)
273		}
274		s2, err := Open(dir)
275		if err != nil {
276			t.Fatalf("重新打开台账失败: %v", err)
277		}
278		t.Cleanup(func() { s2.Close() })
279	
280		replay2, err := s2.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
281		if err != nil {
282			t.Fatalf("重新打开后重放第一次成功的调整仍应成功: %v", err)
283		}
284		checkFirstAdjustView(t, replay2)
285		got2, err := s2.GetBatch("B1")
286		if err != nil {
287			t.Fatalf("重新打开后查询批次失败: %v", err)
288		}
289		checkClosedBatch(got2)
290	}
291	
292	// 两种拒绝必须区分：
293	//   - 沿用已成功的调整请求编号、却更改调整内容 → ErrRequestConflict；
294	//   - 换用尚未使用的请求编号、对已关闭批次提交相同内容 → ErrInvalidState。
295	// 两种拒绝都保留当前批次，且原成功请求仍可取得原结果。
296	func TestUpdateDraftReplayRejections(t *testing.T) {
297		s := openTestStore(t)
298		registerReplayRecipes(t, s)
299		if _, err := s.CreateBatch("b1", "B1", "R1", "v2", 5); err != nil {
300			t.Fatalf("创建批次失败: %v", err)
301		}
302		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8); err != nil {
303			t.Fatalf("第一次调整应成功: %v", err)
304		}
305		if _, err := s.UpdateDraftBatch("u-second", "B1", "R1", "v2", 3); err != nil {
306			t.Fatalf("第二次调整应成功: %v", err)
307		}
308		if _, err := s.StartBatch("s1", "B1"); err != nil {
309			t.Fatalf("开始执行失败: %v", err)
310		}
311		if _, err := s.CloseBatch("c1", "B1"); err != nil {
312			t.Fatalf("关闭批次失败: %v", err)
313		}
314	
315		// 同一请求编号、不同调整内容（改了份数）→ ErrRequestConflict。
316		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 9); !errors.Is(err, ErrRequestConflict) {
317			t.Fatalf("同编号不同份数应返回 ErrRequestConflict，得到 %v", err)
318		}
319		// 同一请求编号、不同调整内容（改了配方版本）→ ErrRequestConflict。
320		if _, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v2", 8); !errors.Is(err, ErrRequestConflict) {
321			t.Fatalf("同编号不同配方应返回 ErrRequestConflict，得到 %v", err)
322		}
323		// 新请求编号、相同内容，但批次已关闭 → ErrInvalidState。
324		if _, err := s.UpdateDraftBatch("u-fresh", "B1", "R1", "v1", 8); !errors.Is(err, ErrInvalidState) {
325			t.Fatalf("新编号对已关闭批次提交应返回 ErrInvalidState，得到 %v", err)
326		}
327	
328		// 两种拒绝都不改动当前批次：仍是已关闭的 R1/v2、3 份。
329		got, err := s.GetBatch("B1")
330		if err != nil {
331			t.Fatalf("查询批次失败: %v", err)
332		}
333		if got.RecipeNo != "R1" || got.RecipeVersion != "v2" || got.PlannedPortions != 3 ||
334			got.Status != StatusClosed {
335			t.Fatalf("拒绝后批次应保持已关闭的 R1/v2、3 份，得到 %+v", got)
336		}
337		mats := materialsMap(got)
338		checkRequirement(t, mats, "M1", "750", "0", "-750")
339		checkRequirement(t, mats, "M4", "6", "0", "-6")
340	
341		// 原成功请求仍可取得原结果。
342		replay, err := s.UpdateDraftBatch("u-first", "B1", "R1", "v1", 8)
343		if err != nil {
344			t.Fatalf("拒绝后原成功请求仍应可重放: %v", err)
345		}
346		checkFirstAdjustView(t, replay)
347	}
