197				return mutatedCreateView(t, good, func(v *BatchView) { v.Materials[0].DifferenceGrams = "0" })
198			}},
199		}
200		for _, tc := range cases {
201			t.Run(tc.name, func(t *testing.T) {
202				dir := t.TempDir()
203				good := setupCreateRequestLedger(t, dir)
204				bad := corruptCreateRequestResult(t, good, func() json.RawMessage { return tc.mutate(good) })
205				if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
206					t.Fatal(err)
207				}
208	
209				s, err := Open(dir)
210				if !errors.Is(err, ErrCorruptData) {
211					t.Fatalf("保存的创建结果损坏应返回 ErrCorruptData，得到 %v", err)
212				}
213				if s != nil {
214					s.Close()
215					t.Fatalf("损坏台账不应返回可用的 Store 对象")
216				}
217				msg := err.Error()
218				for _, want := range []string{"create-b1", "B1"} {
219					if !strings.Contains(msg, want) {
220						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
221					}
222				}
223				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
224				if err != nil {
225					t.Fatal(err)
226				}
227				if !bytes.Equal(got, bad) {
