286	// 原请求对应的批次不存在时，保存的创建结果不能单独作为创建成功的依据：
287	// 即使结果本身内容完整，也按损坏处理。
288	func TestOpenRejectsCreateRequestResultWhenBatchMissing(t *testing.T) {
289		dir := t.TempDir()
290		good := setupCreateRequestLedger(t, dir)
291		var st persistedState
292		if err := json.Unmarshal(good, &st); err != nil {
293			t.Fatal(err)
294		}
295		// 删除 B1，并移除依附于它的后续请求记录（调整、开始、投料、关闭），
296		// 让 create-b1 的批次缺失成为唯一的损坏点。
297		kept := st.Batches[:0]
298		for _, b := range st.Batches {
299			if b.BatchNo != "B1" {
300				kept = append(kept, b)
301			}
302		}
303		st.Batches = kept
304		for _, reqNo := range []string{"u-final", "start-b1", "f1", "f2", "close-b1"} {
305			delete(st.Requests, reqNo)
306		}
307		bad, err := json.MarshalIndent(&st, "", "  ")
308		if err != nil {
309			t.Fatal(err)
310		}
311		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
312			t.Fatal(err)
313		}
314	
315		s, err := Open(dir)
316		if !errors.Is(err, ErrCorruptData) {
317			t.Fatalf("原批次不存在但保留创建结果应返回 ErrCorruptData，得到 %v", err)
318		}
319		if s != nil {
320			s.Close()
321			t.Fatalf("损坏台账不应返回可用的 Store 对象")
322		}
323		msg := err.Error()
324		for _, want := range []string{"create-b1", "B1"} {
325			if !strings.Contains(msg, want) {
326				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
327			}
328		}
329		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
330		if err != nil {
331			t.Fatal(err)
332		}
333		if !bytes.Equal(got, bad) {
334			t.Fatalf("拒绝打开不应改动台账文件")
335		}
336	}
337	
338	// 原提交所选的配方版本不存在时，保存的创建结果不能单独作为创建成功的依据：
339	// 同编号配方的其他版本（R1/v2）即使仍在使用，也不能顶替原选的 R1/v1。
340	func TestOpenRejectsCreateRequestResultWhenRecipeVersionMissing(t *testing.T) {
341		dir := t.TempDir()
342		good := setupCreateRequestLedger(t, dir)
343		var st persistedState
344		if err := json.Unmarshal(good, &st); err != nil {
345			t.Fatal(err)
346		}
347		// 删除 R1/v1：B1 后来已改用 R1/v2，批次绑定仍然完整。依附 R1/v1 的
348		// 配方登记请求记录一并移除，让 create-b1 的原选版本缺失成为唯一的
349		// 损坏点（B3 用 v2，不受影响）。
350		kept := st.Recipes[:0]
351		for _, r := range st.Recipes {
352			if !(r.RecipeNo == "R1" && r.Version == "v1") {
353				kept = append(kept, r)
354			}
355		}
356		st.Recipes = kept
357		delete(st.Requests, "c-recipe-v1")
358		bad, err := json.MarshalIndent(&st, "", "  ")
359		if err != nil {
360			t.Fatal(err)
361		}
362		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
363			t.Fatal(err)
364		}
365	
366		s, err := Open(dir)
367		if !errors.Is(err, ErrCorruptData) {
368			t.Fatalf("原选配方版本不存在但保留创建结果应返回 ErrCorruptData，得到 %v", err)
369		}
370		if s != nil {
371			s.Close()
372			t.Fatalf("损坏台账不应返回可用的 Store 对象")
373		}
374		msg := err.Error()
375		for _, want := range []string{"create-b1", "B1"} {
376			if !strings.Contains(msg, want) {
377				t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
378			}
379		}
380		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
381		if err != nil {
382			t.Fatal(err)
383		}
384		if !bytes.Equal(got, bad) {
385			t.Fatalf("拒绝打开不应改动台账文件")
386		}
387	}
388	
389	// 正常写法差异不能误判为损坏：保存结果的应投量写成 1.000、实投量写成
390	// 0.000、差额写成 -1.000，与首次创建时的数量是同一数值；合法的零实投与
391	// 负差额不是损坏。台账应正常打开，重放仍返回保存的写法。
392	func TestOpenAcceptsCreateRequestResultFormatVariants(t *testing.T) {
393		dir := t.TempDir()
394		good := setupCreateRequestLedger(t, dir)
395	
396		bad := corruptCreateRequestResult(t, good, func() json.RawMessage {
397			return mutatedCreateView(t, good, func(v *BatchView) {
398				v.Materials[0].RequiredGrams = "1.000" // 与 1 是同一数量
399				v.Materials[0].ActualGrams = "0.000"   // 与 0 是同一数量
400				v.Materials[0].DifferenceGrams = "-1.000"
401				v.Materials[1].RequiredGrams = "0.008" // 保持原值
402			})
403		})
404		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
405			t.Fatal(err)
406		}
407	
408		s, err := Open(dir)
409		if err != nil {
410			t.Fatalf("写法差异不应判为损坏: %v", err)
411		}
412		defer s.Close()
413	
414		// 重放取回保存的结果原文：核对项保持 1.000、0.000、-1.000 写法，
415		// 但与首次创建时的数量是同一数值。
416		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
417		if err != nil {
418			t.Fatalf("重放创建请求应成功: %v", err)
419		}
420		if replay.Materials[0].RequiredGrams != "1.000" ||
421			replay.Materials[0].ActualGrams != "0.000" ||
422			replay.Materials[0].DifferenceGrams != "-1.000" {
423			t.Fatalf("重放应返回保存的核对项写法，得到 %+v", replay.Materials[0])
424		}
425	}
426	
427	// 批次后来的调整、开始、投料与关闭都属于批次现状，不能混入第一次创建的
428	// 结果，也不能成为拒绝合法旧结果的理由：台账中 B1 已改选配方、调整份数、
429	// 开始执行、追加投料并关闭，其保存的创建结果仍是首次创建时的内容
430	// （R1/v1、8 份、草稿、空投料、零实投），打开与重放都必须正常；重复提交
431	// 原创建请求继续返回首次结果，查询继续显示当前批次，两者互不覆盖。
432	func TestCreateRequestResultStaysFirstCreateAfterAdjustAndClose(t *testing.T) {
433		dir := t.TempDir()
434		setupCreateRequestLedger(t, dir)
435	
436		s, err := Open(dir)
437		if err != nil {
438			t.Fatalf("已调整并关闭的批次不应让其首次创建结果被判损坏: %v", err)
439		}
440		defer s.Close()
441	
442		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
443		if err != nil {
444			t.Fatalf("重放创建请求应成功: %v", err)
445		}
446		checkFirstCreateView(t, replay)
447		// 查询继续显示当前批次（已关闭、R1/v2、3 份、保留两条投料），
448		// 不被首次创建结果回退。
449		checkClosedCurrentAfterSetup(t, mustGetBatch(t, s, "B1"))
450	}
451	
452	// 台账正常打开后，保存内容中的创建请求结果被改坏：下一次查询或写入必须
453	// 返回 ErrCorruptData——即使本次访问的是另一个正常批次，也不能忽略损坏的
454	// 创建请求；被拒绝的重放不得返回损坏的保存结果，被拒绝的写入不留业务变化、
455	// 不占用请求编号，原台账内容不变。恢复后原成功请求仍可幂等重放，被拒绝过
456	// 的请求编号可以正常使用。
457	func TestCreateRequestResultCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
458		dir := t.TempDir()
459		good := setupCreateRequestLedger(t, dir)
460	
461		s, err := Open(dir)
462		if err != nil {
463			t.Fatal(err)
464		}
465		defer s.Close()
466	
467		// 打开后把 create-b1 的保存结果改坏为空对象（其余记录保持完整）。
468		bad := corruptCreateRequestResult(t, good, func() json.RawMessage {
469			return json.RawMessage(`{}`)
470		})
471		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
472			t.Fatal(err)
473		}
474	
475		// 查询损坏批次与正常批次都必须失败，不能沿用此前读到的内容。
476		for _, batchNo := range []string{"B1", "B3"} {
477			if v, err := s.GetBatch(batchNo); !errors.Is(err, ErrCorruptData) {
478				t.Fatalf("查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
479			} else if v != nil {
480				t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
481			}
482		}
483		// 用原编号、原内容重放损坏的创建请求：不得把损坏的保存结果当成成功
484		// 结果返回，必须报损坏。
485		if _, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8); !errors.Is(err, ErrCorruptData) {
486			t.Fatalf("重放损坏的创建请求应返回 ErrCorruptData，得到 %v", err)
487		}
488		// 对正常批次的新写入同样不能绕过。
489		if _, err := s.StartBatch("start-b3", "B3"); !errors.Is(err, ErrCorruptData) {
490			t.Fatalf("损坏台账上开始正常批次应返回 ErrCorruptData，得到 %v", err)
491		}
492	
493		// 被拒绝的访问不改动文件、不占用请求编号。
494		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
495		if err != nil {
496			t.Fatal(err)
497		}
498		if !bytes.Equal(after, bad) {
499			t.Fatalf("被拒绝的访问不应改动台账文件")
500		}
501		if bytes.Contains(after, []byte("start-b3")) {
502			t.Fatalf("被拒绝的写入不应留下请求记录")
503		}
504	
505		// 恢复后：原成功请求仍取回第一次创建时的结果，被拒绝过的请求编号
506		// 可以正常使用。
507		if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
508			t.Fatal(err)
509		}
510		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
511		if err != nil {
512			t.Fatalf("恢复后重放原成功请求失败: %v", err)
513		}
514		checkFirstCreateView(t, replay)
515		started, err := s.StartBatch("start-b3", "B3")
516		if err != nil {
517			t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
518		}
519		if started.Status != StatusExecuting || started.BatchNo != "B3" {
520			t.Fatalf("B3 应被正常开始执行，得到 %+v", started)
521		}
522	}
523	
524	// 任何一条成功创建请求损坏都应拒绝整份台账：改坏 create-b2 的结果后，
525	// 即使调用方只查询正常的 B1、B3，Open 与后续访问也必须返回
526	// ErrCorruptData。
527	func TestAnyCorruptCreateRequestRejectsWholeLedger(t *testing.T) {
528		dir := t.TempDir()
529		good := setupCreateRequestLedger(t, dir)
530		var st persistedState
531		if err := json.Unmarshal(good, &st); err != nil {
532			t.Fatal(err)
533		}
534		st.Requests["create-b2"].Result = json.RawMessage(`{}`)
535		bad, err := json.MarshalIndent(&st, "", "  ")
536		if err != nil {
537			t.Fatal(err)
538		}
539		if err := os.WriteFile(filepath.Join(dir, stateFileName), bad, 0o644); err != nil {
540			t.Fatal(err)
541		}
542	
543		s, err := Open(dir)
544		if !errors.Is(err, ErrCorruptData) {
545			t.Fatalf("任一创建请求损坏都应返回 ErrCorruptData，得到 %v", err)
546		}
547		if s != nil {
548			s.Close()
549			t.Fatalf("损坏台账不应返回可用的 Store 对象")
550		}
551		if !strings.Contains(err.Error(), "create-b2") {
552			t.Fatalf("错误信息应指出问题请求编号 create-b2，得到 %v", err)
553		}
554	}
555	
556	// 白盒核对：正常台账中 create-b1 的保存结果确实是首次创建时的内容，
557	// 且本文件的改坏辅助函数确实改动了文件内容（防止测试因辅助函数失效而
558	// 假性通过）。
559	func TestCreateRequestCorruptionHelpersWork(t *testing.T) {
560		dir := t.TempDir()
561		good := setupCreateRequestLedger(t, dir)
562	
563		var saved BatchView
564		if err := json.Unmarshal(createResultRaw(t, good, "create-b1"), &saved); err != nil {
565			t.Fatal(err)
566		}
567		if saved.BatchNo != "B1" || saved.RecipeNo != "R1" || saved.RecipeVersion != "v1" ||
568			saved.RecipeName != "配方初版" || saved.PlannedPortions != 8 ||
569			saved.Status != StatusDraft || len(saved.Feedings) != 0 || len(saved.Materials) != 2 {
570			t.Fatalf("正常台账中保存的创建结果应为首次创建内容，得到 %+v", saved)
571		}
572		bad := corruptCreateRequestResult(t, good, func() json.RawMessage {
573			return json.RawMessage(`{}`)
574		})
575		if bytes.Equal(good, bad) {
576			t.Fatal("改坏辅助函数未改动台账内容")
577		}
578		// 正常台账本身必须能打开：所有“正常后续操作不误判”的前提。
579		s, err := Open(dir)
580		if err != nil {
581			t.Fatalf("正常台账应能打开: %v", err)
582		}
583		s.Close()
584		// 每个改坏用例产生的文件都与正常台账不同。
585		for i, mutate := range []func() json.RawMessage{
586			func() json.RawMessage { return nil },
587			func() json.RawMessage { return json.RawMessage("null") },
588			func() json.RawMessage {
589				return mutatedCreateView(t, good, func(v *BatchView) { v.PlannedPortions = 3 })
590			},
591		} {
592			if bytes.Equal(good, corruptCreateRequestResult(t, good, mutate)) {
593				t.Fatalf("第 %d 个改坏用例未改动台账内容", i)
594			}
595		}
596	}
597	
598	// 正常台账上的既有行为保持不变：请求冲突、批次编号重复与返回对象可独立
599	// 修改不受创建结果核对影响。
600	func TestCreateRequestValidationKeepsExistingBehavior(t *testing.T) {
601		dir := t.TempDir()
602		setupCreateRequestLedger(t, dir)
603		s, err := Open(dir)
604		if err != nil {
605			t.Fatal(err)
606		}
607		defer s.Close()
608	
609		// 沿用原请求编号、改变创建内容 → ErrRequestConflict。
610		if _, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 3); !errors.Is(err, ErrRequestConflict) {
611			t.Fatalf("改变创建内容应返回 ErrRequestConflict，得到 %v", err)
612		}
613		// 换未使用的请求编号创建同编号批次 → ErrDuplicateBatch。
614		if _, err := s.CreateBatch("create-fresh", "B1", "R1", "v1", 8); !errors.Is(err, ErrDuplicateBatch) {
615			t.Fatalf("同编号批次应返回 ErrDuplicateBatch，得到 %v", err)
616		}
617		// 重放返回的对象可独立修改，不影响台账与下一次重放。
618		replay, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
619		if err != nil {
620			t.Fatal(err)
621		}
622		replay.PlannedPortions = 99
623		replay.Materials[0].ActualGrams = "42"
624		replay2, err := s.CreateBatch("create-b1", "B1", "R1", "v1", 8)
625		if err != nil {
626			t.Fatal(err)
627		}
628		checkFirstCreateView(t, replay2)
629		if fmt.Sprint(replay2.Materials[0].ActualGrams) != "0" {
630			t.Fatalf("重放结果不应受调用方改写影响: %+v", replay2.Materials[0])
631		}
632	}
